def _marcar_citacao_biblica(texto: str) -> str:
    """Envolve a citação bíblica (parágrafo que começa com 'Do <livro>:') em
    marcadores ⏪DEV0.85⏪ ... ⏪/DEV⏪ para o tts-synth.py aplicar speed 0.85."""
    paragrafos = texto.split("\n\n")
    out = []
    marcado = False
    for p in paragrafos:
        p_strip = p.strip()
        if not marcado and p_strip.startswith("Do ") and "Leitura de" not in p_strip[:30]:
            out.append(f"{DEVAGAR_ABRE} {p_strip} {DEVAGAR_FECHA}")
            marcado = True
        else:
            out.append(p_strip)
